llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Imipramine, a lipophilic tricyclic antidepressant with a dialkylaminopropyl side chain, has absolute oral bioavailability of 47.3 ± 21.4% (range 29–77%) in humans, supporting F ≥ 20% for the query's similar tertiary-amine lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Amitriptyline, another tricyclic antidepressant with a dimethylaminopropyl chain, shows absolute oral bioavailability of 42.8 ± 6.1% in humans, indicating that lipophilic tricyclic tertiary amines are generally orally bioavailable above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fentanyl, an N-phenyl-N-piperidinyl lipophilic tertiary amine, has absolute oral bioavailability of about 32% when swallowed, supporting F ≥ 20% for the query's related N-phenyl-N-indanyl diethylamine structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Delapril, which shares the 1-indanyl amide substructure, has absolute oral bioavailability >55% in humans, showing that the indanyl-containing scaffold does not preclude high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Oxybutynin, a diethylamino-containing lipophilic drug, has low absolute oral bioavailability of about 6% due to extensive first-pass metabolism, but its ester functionality and different scaffold limit direct transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C46"],
      "claim": "Rotigotine has low oral bioavailability in humans, but its phenol/catechol and aminotetralin structure confers conjugation liabilities not present in the query's non-phenolic indanyl aniline system.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic tertiary diamine with an N-phenyl-N-indanyl core and a diethylaminopropyl chain. The most transferable experimental analogues—imipramine, amitriptyline, and fentanyl—show absolute oral bioavailability in the 30–50% range, all above the 20% threshold. Low-bioavailability analogues such as oxybutynin and rotigotine owe their low F to ester or catechol first-pass liabilities that are absent in the query. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "Morgan similarities to evidence molecules are modest (about 0.24–0.30), limiting precise transferability.",
    "First-pass metabolism and possible transporter effects of the diethylaminopropyl aniline/indane system are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

